create table if not exists settings(id int primary key default 1 check(id=1),include_keywords text[] not null default '{}',exclude_keywords text[] not null default '{}',cities text[] not null default '{}',min_score int not null default 60 check(min_score between 0 and 100));
insert into settings(id,include_keywords,exclude_keywords,cities,min_score) values(1,array['auxiliar administrativo','recepcionista','atendente'],array['supervisor','gerente','mei','comissão'],array['maricá','niterói','são gonçalo','home office'],60) on conflict(id) do nothing;
create table if not exists sources(id bigint generated by default as identity primary key,name text not null,kind text not null default 'rss',url text not null unique,enabled boolean not null default true,created_at timestamptz not null default now());
insert into sources(name,kind,url,enabled) values('RioVagas','rss','https://riovagas.com.br/feed/',true) on conflict(url) do nothing;
create table if not exists jobs(id bigint generated by default as identity primary key,source_id bigint references sources(id) on delete set null,external_id text not null unique,title text not null,url text not null,description text,published_at timestamptz,score int not null default 0,status text not null check(status in('approved','ignored')),reasons text[] not null default '{}',notified_at timestamptz,created_at timestamptz not null default now());
create index if not exists jobs_created_at_idx on jobs(created_at desc);create index if not exists jobs_status_idx on jobs(status);
alter table settings enable row level security;alter table sources enable row level security;alter table jobs enable row level security;
